import sys; sys.path.insert(0,'/app/tools'); sys.path.insert(0,'/tmp/w')
import replay
from pathlib import Path
import shelfmark.service as S, shelfmark.config as C, shelfmark.keys as K, shelfmark.routes as R
items=replay.timeline(Path('/app'))
hist=Path('/app/config/history')
svc=None; why={}  # key -> reason last removed
start=[i for i,x in enumerate(items) if x[2]=='started' and x[0]<=replay.to_ms('2027-05-03T14:00:06Z')][-1]
from collections import Counter
cnt=Counter(); out=[]
for at,_,kind,f in items[start:]:
    if kind=='started': svc=S.Service(C.load(hist/f"{f['config']}.toml")); seen={}
    elif kind=='reload': svc.reload(C.load(hist/f"{f['config']}.toml"))
    elif kind=='flush': svc.flush(); seen={}
    elif kind=='request':
        path,_,q=f['target'].partition('?'); m=R.match(path)
        before=dict(svc.cache.entries)
        got=svc.handle(f['method'],f['target'],f['lang'],at)
        if got=='miss':
            key=K.build(m[0],m[1],K.parse_query(q),f['lang'],svc.cfg)
            if key in seen and f['cache']=='miss':
                out.append((f['id'],f['time'],f['target'],f['lang'],key,seen[key],at-seen[key][0]))
            seen[key]=(at,)
        elif got=='hit': pass
        if f['method']=='PURGE':
            pass
print(len(out))
for o in out[:40]: print(o)
